 complete=g[g.账户状态.eq('新回放完整')|g.账户状态.eq('已有完整回放')];a=complete['账户收益%'];dd=complete['最大收盘回撤%'];v=g['选中D1D2连续封板率%日均'] if '选中D1D2连续封板率%日均' in g else g['选中D1D2连续封板率%'];r=g['随机D1D2连续封板率%'];s=g['选中D2收盘收益%日均'];t=g['随机D2收盘收益%日均'];annual.append({'年份':year,'月份总数':len(g),'完整结算月数':len(complete),'未结清月数':int(g.账户状态.eq('持仓未结清').sum()),'完整月盈利数':int(a.gt(0).sum()),'完整月亏损数':int(a.lt(0).sum()),'月收益中位数%':a.median(),'最差月收益%':a.min(),'最佳月收益%':a.max(),'月内最大收盘回撤%':dd.max(),'买入笔数':int(complete['假设买入笔数'].fillna(0).sum()),'涨停价买入笔数':int(complete['涨停价买入笔数'].fillna(0).sum()),'连板率高于随机的月数':int((v>r).sum()),'D2价格收益高于随机的月数':int((s>t).sum()),'备注':'月度独立账户，不是全年连续账户'})
